Detect the use of `msg.value` inside a loop.

For example:
```solidity
contract MsgValueInLoop{
    mapping (address => uint256) balances;

    function bad(address[] memory receivers) public payable {
        for (uint256 i=0; i < receivers.length; i++) {
            balances[receivers[i]] += msg.value;
        }
    }
}
```

Memory Manipulation: This vulnerability occurs when a contract's memory-related operations are improperly handled, leading to unintended behavior or potential security risks. Memory manipulation vulnerabilities can result from incorrect access or modification of memory storage, causing unexpected outcomes.

For example:

```solidity
contract MemoryManipulation {
    uint256 public value;

    function setValue(uint256 _value) public {
        uint256[] memory array = new uint256[](1);
        array[0] = _value;
        assembly {
            mstore(add(value, 0x20), mload(add(array, 0x20)))
        }
    }
}
```

In this example, the memory manipulation vulnerability is demonstrated through the use of inline assembly to modify the contract's `value` state variable. The misuse of memory operations in this manner can lead to unintended behavior or potential security risks.

Detect `delegatecall` inside a loop in a payable function. When using `delegatecall` in a payable function, the msg.value will be passed to the target contract. The amount or balance will be accredited multiple times if we use this inside a loop.

For example:

```solidity
contract DelegatecallInLoop{

    mapping (address => uint256) balances;

    function bad(address[] memory receivers) public payable {
        for (uint256 i = 0; i < receivers.length; i++) {
            address(this).delegatecall(abi.encodeWithSignature("addBalance(address)", receivers[i]));
        }
    }

    function addBalance(address a) public payable {
        balances[a] += msg.value;
    } 

}
```
When calling bad the same `msg.value` amount will be accredited multiple times.
